CREATE TABLE SYS_ROLE
(
    ID VARCHAR2(64) NOT NULL ENABLE,
    ROLE_NAME VARCHAR2(400),
    ROLE_CODE VARCHAR2(200) NOT NULL ENABLE,
    TENANT_CODE VARCHAR2(32),
    ROLE_TYPE NUMBER(1,0),
    PRIMARY KEY (id)
)  ;
comment on table SYS_ROLE is '角色表';
comment on column SYS_ROLE.id is '主键ID';


commit;